resource "aws_iam_policy" "jenkins_deploy_policy" {
  name        = "jenkins-deploy-policy"
  description = "Policy for jenkins-deploy user"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowLambdaDeployment"
        Effect    = "Allow"
        Action    = [
          "lambda:CreateFunction",
          "lambda:UpdateFunctionCode",
          "lambda:PublishVersion",
          "lambda:UpdateFunctionConfiguration",
          "lambda:GetFunction",
          "lambda:GetFunctionConfiguration",
          "lambda:ListVersionsByFunction",
        ]
        Resource = "*"
      },
      {
        Sid       = "AllowCloudFormationDeployment"
        Effect    = "Allow"
        Action    = [
          "cloudformation:CreateStack",
          "cloudformation:UpdateStack",
          "cloudformation:DescribeStacks",
          "cloudformation:DescribeStackEvents",
          "cloudformation:DescribeStackResources",
          "cloudformation:ListStacks",
        ]
        Resource = "*"
      },
      {
        Sid       = "AllowIAMPassRole"
        Effect    = "Allow"
        Action    = "iam:PassRole"
        Resource = "*"
      },
      {
        Sid       = "AllowCloudFormationExecutionRole"
        Effect    = "Allow"
        Action    = "iam:CreateRole"
        Resource = "arn:aws:iam::*:role/*"
      },
    ]
  })
}

